// Prepare Request
// - Cleans incoming data
// - Validates required fields
// - Builds a structured context for the AI Agent
// - Never invents missing information

const body = $input.first().json.body || $input.first().json;

const required = [
  'company_id',
  'company_name',
  'service',
  'objective',
  'audience',
  'platform',
  'ad_types',
  'campaign_request'
];

const missing = required.filter((field) => {
  const value = body[field];
  if (value === undefined || value === null || value === '') return true;
  if (Array.isArray(value) && value.length === 0) return true;
  return false;
});

if (missing.length > 0) {
  return [{
    json: {
      status: 'missing_information',
      missing_fields: missing
    }
  }];
}

const session_id = `${body.company_id}_${Date.now()}`;

return [{
  json: {
    status: 'ok',
    session_id,
    context: {
      company_id: body.company_id,
      company_name: body.company_name,
      service: body.service,
      objective: body.objective,
      audience: body.audience,
      platform: body.platform,
      ad_types: body.ad_types,
      campaign_request: body.campaign_request
    }
  }
}];

// DEMO / PLACEHOLDER DATA ONLY
// TODO: replace this block with a real database call (Supabase / PostgreSQL / HTTP Request)
const companyId = query || 'company_001';

const demoDatabase = {
  company_001: {
    company_id: 'company_001',
    company_name: 'DEMO_PLACEHOLDER - بن ذياب قطينة للصرافة والتحويلات',
    services: ['DEMO_PLACEHOLDER - الحوالات المالية', 'DEMO_PLACEHOLDER - صرافة العملات'],
    brand_identity: {
      colors: ['DEMO_PLACEHOLDER'],
      typography: 'DEMO_PLACEHOLDER',
      tone_of_voice: 'DEMO_PLACEHOLDER - رسمي وموثوق'
    },
    audience: 'DEMO_PLACEHOLDER',
    approved_claims: ['DEMO_PLACEHOLDER - حوالتك بسهولة وأمان'],
    business_rules: ['DEMO_PLACEHOLDER - لا تذكر أي سعر صرف أو رسوم أو وقت تحويل غير موثق هنا']
  }
};

const record = demoDatabase[companyId];

if (!record) {
  return {
    found: false,
    message: 'DEMO_PLACEHOLDER: لا توجد بيانات لهذه الشركة في قاعدة البيانات التجريبية. يجب ربط قاعدة بيانات حقيقية.'
  };
}

return { found: true, ...record };

let input;
try {
  input = JSON.parse(query);
} catch (e) {
  input = {};
}

const copy = input.copy || {};
const approvedClaims = input.approved_claims || [];
const issues = [];

const forbiddenPatterns = [
  /\d+\s*%/,
  /خلال\s*\d+\s*(دقيق|ساع|يوم)/,
  /مجانًا\s*100/,
  /ضمان\s*مطلق/
];

const textToCheck = [copy.headline, copy.body, copy.cta, copy.caption].filter(Boolean).join(' ');

forbiddenPatterns.forEach((pattern) => {
  if (pattern.test(textToCheck)) {
    const isApproved = approvedClaims.some((claim) => textToCheck.includes(claim));
    if (!isApproved) {
      issues.push('تم رصد ادعاء مالي محتمل غير موثّق (نسبة/رسوم/وقت/ضمان) غير موجود ضمن approved_claims.');
    }
  }
});

if (!copy.headline || !copy.body || !copy.cta) {
  issues.push('حقول النص الإعلاني الأساسية غير مكتملة (headline/body/cta).');
}

const score = issues.length === 0 ? 90 : Math.max(40, 90 - issues.length * 20);

return {
  approved: issues.length === 0,
  score,
  issues,
  recommended_fixes: issues.length
    ? ['أعد صياغة الادعاءات المالية بالاعتماد فقط على approved_claims، أو أكمل الحقول الناقصة.']
    : [],
  note: 'هذا فحص آلي أساسي (Rule-Based). أكمل المراجعة اللغوية والتسويقية النوعية بنفسك.'
};

const agentOutput = $json.output || $json;
const context = $('Prepare Request').item.json.context;

const campaign_id = `${context.company_id}_${Date.now()}`;
const campaign = agentOutput.campaign || {};

return [{
  json: {
    campaign_id,
    company_id: context.company_id,
    request: context.campaign_request,
    status: agentOutput.status || 'unknown',
    strategy: JSON.stringify(campaign.strategy || {}),
    copy: JSON.stringify(campaign.copy || {}),
    image_prompt: JSON.stringify(campaign.image || {}),
    video_prompt: JSON.stringify(campaign.video || {}),
    quality_score: campaign.quality_control ? campaign.quality_control.score : null,
    created_at: new Date().toISOString(),
    agent_output: agentOutput
  }
}];

const input = $input.first().json;

if (input.status === 'missing_information') {
  return [{
    json: {
      status: 'missing_information',
      missing_fields: input.missing_fields
    }
  }];
}

const agentOutput = input.agent_output || {};
const campaign = agentOutput.campaign || {};

if (agentOutput.status === 'manual_review_required') {
  return [{
    json: {
      status: 'manual_review_required',
      reason: agentOutput.reason || '',
      issues: agentOutput.issues || []
    }
  }];
}

return [{
  json: {
    status: 'approved',
    campaign_id: input.campaign_id,
    company: { company_id: input.company_id },
    strategy: campaign.strategy || {},
    copy: campaign.copy || {},
    image: campaign.image || {},
    video: campaign.video || {},
    quality_control: campaign.quality_control || {},
    assets: {}
  }
}];
